using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System;
using System.IO;
using System.Linq;
using ConRoi.Investigation.V36.R104;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var sc = EditorSceneManager.GetActiveScene();
            if (EditorApplication.isPlaying || !sc.path.EndsWith("r104.unity"))
                throw new Exception("Edit r104 required");
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            var clip = s.clipGate.transform.parent;
            foreach (var l in clip.GetComponentsInChildren<LineRenderer>(true).Where(l => l.name.StartsWith("R12_suspension_")))
            {
                var p = l.GetPosition(0);
                p.y = 5.3f;
                p.z = 1.25f;
                l.SetPosition(0, p);
            }

            foreach (var rr in s.GetComponentsInChildren<Renderer>(true))
                if (rr.name.StartsWith("R12_stand") || rr.name.StartsWith("R12_overhead"))
                {
                    var mat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Art/InvestigationV36/R104/Materials/R104_repair_stand_final.mat");
                    if (!mat)
                    {
                        mat = new Material(Shader.Find("Universal Render Pipeline/Lit"));
                        mat.color = new Color(.24f, .14f, .06f);
                        AssetDatabase.CreateAsset(mat, "Assets/Art/InvestigationV36/R104/Materials/R104_repair_stand_final.mat");
                    }

                    rr.sharedMaterial = mat;
                }

            s.data = new InvestigationSave();
            s.diagnostics = false;
            EditorSceneManager.MarkSceneDirty(sc);
            EditorSceneManager.SaveScene(sc);
            AssetDatabase.SaveAssets();
            r.Log("Final source support/context integrated, clean profile authored");
        }
    }
}

